type Commitment = Row & {
  description: string;
  progress: string;
  beneficiary: string;
  wait_id: string | null;
};

type Workflow = Row & {
  steps: Array<{ id: string; description: string; state: string }>;
  execution?: unknown;
};

type Proposal = {
  id: string;
  decision: string;
  candidate: { action: string | { text?: string } };
};

type WorkData = {
  goals: Goal[];
  commitments: Commitment[];
  schedules: Schedule[];
  workflows: Workflow[];
  work: Work[];
  children: Work[];
  inbox: Proposal[];
};

type Editor = {
  kind: "goal" | "commitment" | "schedule" | "workflow";
  goal?: Goal;
} | null;

