              >
                <ArrowUp size={15} />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                aria-label={`Move ${model} down`}
                disabled={index === selected.length - 1}
                onClick={() => move(index, 1)}
              >
                <ArrowDown size={15} />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                aria-label={`Remove ${model}`}
                onClick={() =>
                  setSelected((current) =>
                    current.filter((item) => item !== model),
                  )
                }
              >
                <X size={15} />
              </Button>
            </li>
          ))}
        </ol>
        {action.error && (
          <p role="alert" className="gateway-error">
            {action.error}
