        ),
      )
      .mockImplementationOnce(async () => reply({ ok: true }));
    vi.stubGlobal("fetch", fetcher);
    const hook = mount();
    await execute(hook);
    const initial = JSON.parse(sessionStorage.getItem(key)!);
