    type: "object",
    properties: { detail: { type: "boolean" } },
    additionalProperties: false,
  };
  fireEvent.change(screen.getByLabelText("Options (JSON)"), {
    target: {
      value: JSON.stringify({
        operations: { read_status: readSchema, undeclared: { type: "object" } },
      }),
